Plan: Read the stage-to-probability mapping from the Data sheet. For Opportunities rows 2–3, multiply Est. Revenue by the probability matching the Pipeline Stage. Write the resulting plain values into Opportunities!G2:G3.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

data_ws = vals["Data"]
prob_map = {}
for row in data_ws.iter_rows(min_row=1, max_row=data_ws.max_row, min_col=1, max_col=2):
    stage = row[0].value
    prob = row[1].value
    if stage is None:
        continue
    try:
        prob_map[str(stage).strip()] = float(prob)
    except (TypeError, ValueError):
        continue

opp_vals = vals["Opportunities"]
opp_ws = wb["Opportunities"]

for r in range(2, 4):
    stage = opp_vals.cell(row=r, column=4).value
    revenue = opp_vals.cell(row=r, column=5).value

    if stage is None or revenue is None:
        result = None
    else:
        try:
            revenue_f = float(revenue)
        except (TypeError, ValueError):
            result = None
        else:
            probability = prob_map.get(str(stage).strip())
            if probability is None:
                result = 0.0
            else:
                result = revenue_f * probability

    opp_ws.cell(row=r, column=7).value = result
    print(f"Row {r}: stage={stage!r}, revenue={revenue!r}, weighted={result!r}")

wb.save(OUT)
